def loss(w):
    r = X @ w - y
    return r @ r / len(y)

def grad(w):
    return 2 / len(y) * X.T @ (X @ w - y)

w = np.zeros(2)
print(loss(w), grad(w))

def descend(X, y, lr, steps=50):
    w = np.zeros(X.shape[1])
    for _ in range(steps):
        w = w - lr * 2 / len(y) * X.T @ (X @ w - y)
    return np.mean((X @ w - y) ** 2)

for lr in (0.01, 0.05, 0.11, 0.13):
