    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y, dtype=float)
        n, d = X.shape
        self.coef_, self.intercept_, self.loss_history_ = np.zeros(d), 0.0, []
        # TODO: up to max_iter times:
        #   residual = X @ coef_ + intercept_ - y, and append its mean square to loss_history_
        #   grad_w = (2 / n) X^T residual and grad_b = 2 * mean(residual)
        #   if the gradient's length, sqrt(|grad_w|^2 + grad_b^2), is below tol, stop (break)
        #   otherwise step: coef_ -= lr * grad_w and intercept_ -= lr * grad_b
        # Keep the number of steps taken in self.n_iter_.
        raise NotImplementedError
        return self

    def predict(self, X):
        return np.asarray(X, dtype=float) @ self.coef_ + self.intercept_


