class LogisticRegressionGD:
    """Binary logistic regression, trained by gradient descent on the mean log-loss plus an L2 penalty.
    The penalty is |w|^2 / (2 C n), which makes C mean what it means in scikit-learn: smaller C, more penalty."""

    def __init__(self, C=1.0, lr=0.5, max_iter=100_000, tol=1e-8):
        self.C, self.lr, self.max_iter, self.tol = C, lr, max_iter, tol

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y, dtype=float)
        n, d = X.shape
        lam = 1 / (self.C * n)
        self.coef_, self.intercept_ = np.zeros(d), 0.0
