import numpy as np


def entropy(y):
    """The sum of p log2(1/p) over the classes present in y (the same as -sum p log2 p): 0 for a pure node,
    1 bit for a 50/50 mix of two classes."""
    raise NotImplementedError


def gini(y):
    """1 - sum of p^2: the chance that two labels drawn at random (with replacement) from y differ."""
    raise NotImplementedError


def information_gain(y, left, impurity=entropy):
    """The impurity of y minus the size-weighted impurity of its two parts; left is a boolean mask."""
    raise NotImplementedError


def best_split(X, y, impurity=entropy):
    """The (gain, feature, threshold) with the highest gain, trying every feature and every threshold halfway
    between two neighbouring distinct values. (0.0, None, None) when no split improves purity."""
    best = (0.0, None, None)
    # TODO: for each feature j: values = np.unique(X[:, j]); thresholds = (values[:-1] + values[1:]) / 2;
    #       for each threshold t: gain = information_gain(y, X[:, j] <= t, impurity);
    #       keep it only if gain > best gain + 1e-12, so that the first of two equal splits wins
    raise NotImplementedError
    return best


class DecisionTreeClassifier:
    def __init__(self, max_depth=None, min_samples_split=2, criterion="entropy"):
        self.max_depth, self.min_samples_split = max_depth, min_samples_split
        self.impurity = entropy if criterion == "entropy" else gini

    def fit(self, X, y):
        self.classes_, codes = np.unique(y, return_inverse=True)
        self.root_ = self._grow(np.asarray(X, dtype=float), codes, depth=0)
        return self

    def _grow(self, X, y, depth):
        """A leaf is {"counts": class counts}; a split node also has feature, threshold, gain, left and right."""
        counts = np.bincount(y, minlength=len(self.classes_))
        # TODO: return a leaf if the node is pure, has fewer than min_samples_split rows, is at max_depth
        #       (when max_depth isn't None), or best_split finds no split. Otherwise split on the best feature
        #       and threshold, and grow the left child from the rows with X[:, feature] <= threshold, the right
        #       child from the rest, both at depth + 1.
        raise NotImplementedError

    def _leaf(self, x):
        node = self.root_
        while "feature" in node:
            node = node["left"] if x[node["feature"]] <= node["threshold"] else node["right"]
        return node

    def predict_proba(self, X):
        return np.array([self._leaf(x)["counts"] / self._leaf(x)["counts"].sum() for x in np.asarray(X, dtype=float)])

    def predict(self, X):
        return self.classes_[self.predict_proba(X).argmax(axis=1)]

    def n_leaves(self, node=None):
        node = node or self.root_
        return 1 if "feature" not in node else self.n_leaves(node["left"]) + self.n_leaves(node["right"])

    def splits(self, node=None):
        """Every node, depth first and left before right, as (feature, threshold); leaves are (-2, -2), as in
        scikit-learn's tree_.feature and tree_.threshold arrays."""
        node = node or self.root_
        if "feature" not in node:
            return [(-2, -2.0)]
        return [(node["feature"], node["threshold"])] + self.splits(node["left"]) + self.splits(node["right"])

    def export_text(self, feature_names):
        """The tree laid out like sklearn.tree.export_text, so the two can be compared line by line."""
        lines = []

        def walk(node, indent):
            if "feature" not in node:
                lines.append(f"{indent}|--- class: {self.classes_[node['counts'].argmax()]}")
                return
            name, t = feature_names[node["feature"]], node["threshold"]
            lines.append(f"{indent}|--- {name} <= {t:.2f}")
            walk(node["left"], indent + "|   ")
            lines.append(f"{indent}|--- {name} >  {t:.2f}")
            walk(node["right"], indent + "|   ")

        walk(self.root_, "")
        return "\n".join(lines) + "\n"
